#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>
#include <time.h>

/* K8s auth token validation library - handles service account tokens */
/* Deployed as sidecar container for mTLS termination */

#define MAX_SESSIONS 4096
#define TOKEN_LEN 64
#define BUCKET_COUNT 256

typedef struct session_node {
    char token[TOKEN_LEN];
    uint64_t expiry;
    uint32_t uid;
    struct session_node *next;
} session_node_t;

typedef struct {
    session_node_t *buckets[BUCKET_COUNT];
    int total_sessions;
} session_store_t;

static session_store_t g_store = {0};

/* HMAC-based keyed hash to prevent adversarial bucket collisions */
static uint8_t hash_key[16] = {0};
static int key_initialized = 0;

static void ensure_key_init(void) {
    if (!key_initialized) {
        FILE *f = fopen("/dev/urandom", "r");
        if (f) {
            size_t got = fread(hash_key, 1, 16, f);
            fclose(f);
            /* Only treat the key as initialized if we obtained a full
             * 16 bytes of randomness; otherwise abort rather than
             * silently falling back to a predictable all-zero key. */
            if (got == 16) {
                key_initialized = 1;
                return;
            }
        }
        /* Failed to obtain secure randomness: do not proceed with a
         * predictable key. */
        fprintf(stderr, "FATAL: unable to initialize secure hash key\n");
        abort();
    }
}

/* SipHash-2-4 inspired keyed hash for session token lookup */
static uint32_t token_hash(const char *token, size_t len) {
    ensure_key_init();
    uint64_t v0 = 0x736f6d6570736575ULL;
    uint64_t v1 = 0x646f72616e646f6dULL;
    uint64_t v2 = 0x6c7967656e657261ULL;
    uint64_t v3 = 0x7465646279746573ULL;
    uint64_t k0, k1;
    memcpy(&k0, hash_key, 8);
    memcpy(&k1, hash_key + 8, 8);
    v0 ^= k0; v1 ^= k1; v2 ^= k0; v3 ^= k1;

    for (size_t i = 0; i < len; i++) {
        uint64_t m = (uint64_t)(uint8_t)token[i];
        v3 ^= m;
        /* Two SipRounds */
        v0 += v1; v1 = (v1 << 13) | (v1 >> 51); v1 ^= v0;
        v0 = (v0 << 32) | (v0 >> 32);
        v2 += v3; v3 = (v3 << 16) | (v3 >> 48); v3 ^= v2;
        v0 += v3; v3 = (v3 << 21) | (v3 >> 43); v3 ^= v0;
        v2 += v1; v1 = (v1 << 17) | (v1 >> 47); v1 ^= v2;
        v2 = (v2 << 32) | (v2 >> 32);
        v0 += v1; v1 = (v1 << 13) | (v1 >> 51); v1 ^= v0;
        v0 = (v0 << 32) | (v0 >> 32);
        v2 += v3; v3 = (v3 << 16) | (v3 >> 48); v3 ^= v2;
        v0 += v3; v3 = (v3 << 21) | (v3 >> 43); v3 ^= v0;
        v2 += v1; v1 = (v1 << 17) | (v1 >> 47); v1 ^= v2;
        v2 = (v2 << 32) | (v2 >> 32);
        v0 ^= m;
    }
    v2 ^= 0xff;
    /* Four finalization rounds */
    for (int r = 0; r < 4; r++) {
        v0 += v1; v1 = (v1 << 13) | (v1 >> 51); v1 ^= v0;
        v0 = (v0 << 32) | (v0 >> 32);
        v2 += v3; v3 = (v3 << 16) | (v3 >> 48); v3 ^= v2;
        v0 += v3; v3 = (v3 << 21) | (v3 >> 43); v3 ^= v0;
        v2 += v1; v1 = (v1 << 17) | (v1 >> 47); v1 ^= v2;
        v2 = (v2 << 32) | (v2 >> 32);
    }
    return (uint32_t)((v0 ^ v1 ^ v2 ^ v3) % BUCKET_COUNT);
}

/* Rate limiter state per source IP */
#define MAX_IPS 1024
typedef struct {
    uint32_t ip;
    int attempts;
    time_t window_start;
} rate_entry_t;

static rate_entry_t rate_table[MAX_IPS];
static int rate_count = 0;

static int check_rate_limit(uint32_t source_ip) {
    time_t now = time(NULL);
    for (int i = 0; i < rate_count; i++) {
        if (rate_table[i].ip == source_ip) {
            if (now - rate_table[i].window_start > 60) {
                rate_table[i].attempts = 1;
                rate_table[i].window_start = now;
                return 1;
            }
            if (rate_table[i].attempts >= 100) {
                return 0; /* rate limited */
            }
            rate_table[i].attempts++;
            return 1;
        }
    }
    if (rate_count < MAX_IPS) {
        rate_table[rate_count].ip = source_ip;
        rate_table[rate_count].attempts = 1;
        rate_table[rate_count].window_start = now;
        rate_count++;
    }
    return 1;
}

/* Insert a new session token after successful authentication */
int session_insert(const char *token, uint32_t uid, uint64_t ttl_seconds) {
    if (g_store.total_sessions >= MAX_SESSIONS) {
        return -1; /* store full */
    }
    size_t len = strnlen(token, TOKEN_LEN);
    uint32_t idx = token_hash(token, len);

    session_node_t *node = calloc(1, sizeof(session_node_t));
    if (!node) return -1;

    memcpy(node->token, token, len);
    node->uid = uid;
    node->expiry = (uint64_t)time(NULL) + ttl_seconds;

    /* Prepend to bucket chain */
    node->next = g_store.buckets[idx];
    g_store.buckets[idx] = node;
    g_store.total_sessions++;
    return 0;
}

/* Validate a bearer token from incoming request */
int session_validate(const char *token, uint32_t source_ip, uint32_t *out_uid) {
    if (!check_rate_limit(source_ip)) {
        return -2; /* rate limited */
    }

    size_t len = strnlen(token, TOKEN_LEN);
    uint32_t idx = token_hash(token, len);
    uint64_t now = (uint64_t)time(NULL);

    session_node_t *cur = g_store.buckets[idx];
    while (cur != NULL) {
        /* Constant-time comparison to prevent timing attacks.
         * Only compare up to the actual token length to avoid reading
         * past the end of a caller-supplied buffer shorter than
         * TOKEN_LEN. A length mismatch counts as a difference so that
         * a shorter input never matches a longer stored token. */
        volatile int diff = 0;
        size_t stored_len = strnlen(cur->token, TOKEN_LEN);
        diff |= (int)(stored_len ^ len);
        for (size_t i = 0; i < len; i++) {
            diff |= cur->token[i] ^ token[i];
        }
        if (diff == 0 && cur->expiry > now) {
            *out_uid = cur->uid;
            return 0; /* valid */
        }
        cur = cur->next;
    }
    return -1; /* not found */
}

/* Periodic cleanup of expired sessions - called by k8s liveness probe handler */
void session_gc(void) {
    uint64_t now = (uint64_t)time(NULL);
    for (int i = 0; i < BUCKET_COUNT; i++) {
        session_node_t **pp = &g_store.buckets[i];
        while (*pp) {
            if ((*pp)->expiry <= now) {
                session_node_t *expired = *pp;
                *pp = expired->next;
                memset(expired->token, 0, TOKEN_LEN);
                free(expired);
                g_store.total_sessions--;
            } else {
                pp = &(*pp)->next;
            }
        }
    }
}

/* Health check endpoint for k8s readiness probe */
int health_check(void) {
    return (g_store.total_sessions < MAX_SESSIONS) ? 0 : -1;
}
